+    margin-bottom: 1.5rem;
+}
+
+::deep .filter-section h3 {
+    font-size: 0.9rem;
+    margin-bottom: 0.5rem;
+}
+
+::deep .filter-checkbox {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    margin-bottom: 0.3rem;
+    cursor: pointer;
+}
+
+::deep .filter-section input[type="number"] {
+    width: 100%;
+    padding: 0.3rem;
+    margin-top: 0.25rem;
+    border: 1px solid #ccc;
+    border-radius: 4px;
+}
+
+::deep .filter-actions {
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+::deep .btn-apply {
+    padding: 0.5rem;
+    background: #0d6efd;
+    color: white;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+::deep .btn-clear {
+    padding: 0.5rem;
+    background: transparent;
+    border: 1px solid #ccc;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+::deep .catalog-pagination {
+    display: flex;
+    justify-content: center;
+    gap: 0.5rem;
+    padding: 1rem 0;
+}
+
+::deep .btn-page {
+    padding: 0.4rem 0.8rem;
+    border: 1px solid #ccc;
+    background: white;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+::deep .btn-page.active {
+    background: #0d6efd;
+    color: white;
+    border-color: #0d6efd;
+}
+
+::deep .btn-page:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
